import type { Author, DBAuthor } from '~/types/bluebird';

export const customAuthorOrder = [
  'polka_lion',
  'My_Mai_Eld',
  'hanabistarmine',
  'G_Akky304250',
  'MiracleGoldSP',
  'Noricco_U',
  'Yukuri_talk',
  'Rollie_twinkle',
  'LittlegreenCom',
  'ShaunTheBunny'
];

export const sortAuthorsByCustomOrder = <T extends DBAuthor | Author | { userName: string }>(
  authors: T[]
): T[] => {
  const sortedAuthors = authors.sort((a, b) => {
    const aIndex = customAuthorOrder.indexOf(a.userName);
    const bIndex = customAuthorOrder.indexOf(b.userName);

    if (aIndex === -1 && bIndex === -1) return 0;
    if (aIndex === -1) return 1;
    if (bIndex === -1) return -1;

    return aIndex - bIndex;
  });
  return sortedAuthors;
};
